input.command:
docker exec -w /workspace sc-run-20261120-103212-exp-L2b bash -lc 'cd /tmp/base && for cfg in "base 0" "new 0"; do set -- $cfg; d=/tmp/run_$1; mkdir -p $d; cp -r /tmp/base/dev $d/; if [ $1 = base ]; then cp /tmp/losses_orig.py $d/losses.py; else cp /workspace/losses.py $d/losses.py; fi; (cd $d && MINI_EXTRA_TOKENS=200 XLA_FLAGS=--xla_cpu_multi_thread_eigen=false python dev/mini.py --seed=1 --out=$d/x.jsonl > $d/x.log 2>&1 && python dev/summarize.py $d/x.jsonl | tail -4 > $d/x.sum) & done; 
d=/tmp/run_new; (cd /tmp && mkdir -p run_tis && cp -r /tmp/base/dev run_tis/ && cp /workspace/losses.py run_tis/ && cd run_tis && python dev/mini.py --seed=2 --out=/tmp/run_tis/x.jsonl rl.is.high=2.0 rl.is.outside=clamp > x.log 2>&1 && python dev/summarize.py x.jsonl | tail -4 > x.sum) &
wait; for d in base new tis; do echo == $d; cat /tmp/run_$d/x.sum; done'

